struct Standard {
    const char* name;
    long value;  // __cplusplus in a file built as this standard
};

const Standard kStandards[] = {
    {"C++98", 199711L}, {"C++11", 201103L}, {"C++14", 201402L}, {"C++17", 201703L},
    {"C++20", 202002L}, {"C++23", 202302L}, {"C++26 draft", 202400L},
};

int main() {
    std::cout << "__cplusplus: " << __cplusplus << '\n';
    const char* newest = "none";
    for (const Standard& s : kStandards) {
        const bool has = __cplusplus >= s.value;  // >=, never ==
        std::cout << s.name << ": " << (has ? "yes" : "no") << '\n';
        if (has) newest = s.name;
    }
    std::cout << "newest: " << newest << '\n';
    return 0;
}

