#include <algorithm>
#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <vector>

// C++98: a function object, a spelled-out iterator type, NULL, and new with a matching delete
struct IsBuy {
    bool operator()(int qty) const { return qty > 0; }
};

long net_98(const std::map<std::string, int>& position) {
    long total = 0;
    for (std::map<std::string, int>::const_iterator it = position.begin(); it != position.end(); ++it) {
        total += it->second;
    }
    return total;
}

// C++11: auto, range-for, a lambda, braces, nullptr, unique_ptr, enum class, static_assert
long net_11(const std::map<std::string, int>& position) {
    long total = 0;
    for (const auto& entry : position) total += entry.second;
    return total;
}

enum class Side { Buy, Sell };
static_assert(sizeof(long long) >= 8, "long long holds at least 64 bits");

int main() {
    std::vector<int> fills98;  // C++98 filled a vector one push_back at a time
    fills98.push_back(100);
    fills98.push_back(-50);
    fills98.push_back(200);
    const std::vector<int> fills11 = {100, -50, 200};
    std::cout << "buys: " << std::count_if(fills98.begin(), fills98.end(), IsBuy()) << ' '
              << std::count_if(fills11.begin(), fills11.end(), [](int q) { return q > 0; }) << '\n';

    std::map<std::string, int> position;
    position["AAPL"] = 300;
    position["MSFT"] = -50;
    std::cout << "net: " << net_98(position) << ' ' << net_11(position) << '\n';

    int* order98 = new int(42);  // yours to delete, on every path out of the function
    std::cout << "order: " << *order98;
    delete order98;
    order98 = NULL;
    const std::unique_ptr<int> order11(new int(42));  // deleted for you at the closing brace
    std::cout << ' ' << *order11 << '\n';

    int* none = nullptr;
    const Side side = Side::Sell;
    std::cout << "null: " << (order98 == 0) << ' ' << (none == nullptr) << ", sell: " << (side == Side::Sell)
              << '\n';
    return 0;
}

