// C++14
constexpr long long kMaxQty = 1'000'000;  // digit separators
constexpr unsigned kFlags = 0b1010;       // binary literal

constexpr long long pow10(int n) {  // a loop and a local in constexpr
    long long p = 1;
    for (int i = 0; i < n; ++i) p *= 10;
    return p;
}

auto notional(long long qty, long long px) { return qty * px; }  // the return type is deduced

// C++17
inline constexpr int kLot = 100;  // an inline variable

template <typename... Ts>
auto total(Ts... xs) { return (xs + ... + 0); }  // a fold expression

[[nodiscard]] std::optional<long long> parse_qty(std::string_view text) {
    long long q = 0;
    const auto [end, ec] = std::from_chars(text.data(), text.data() + text.size(), q);
    if (ec != std::errc{} || end != text.data() + text.size()) return std::nullopt;
    return q;
}

template <typename T>
std::string kind(const T&) {
    if constexpr (std::is_integral_v<T>) return "integer";  // only the branch that fits compiles
    else return "other";
}

int main() {
    auto twice = [](auto x) { return x * 2; };  // C++14 generic lambda
    std::cout << twice(21) << ' ' << twice(1.25) << ' ' << pow10(3) << ' ' << kFlags << '\n';
    const auto px = std::make_unique<long long>(19275);  // C++14 make_unique
    std::cout << notional(kLot, *px) << ' ' << (kMaxQty > notional(10, 10)) << '\n';

    const std::map<std::string, int> position{{"AAPL", 300}, {"MSFT", -50}};
    for (const auto& [symbol, qty] : position) std::cout << symbol << '=' << qty << ' ';  // C++17 bindings
    std::cout << '\n';

    if (const auto q = parse_qty("250"); q) std::cout << "qty " << *q << '\n';  // C++17 if with an init
    std::cout << "bad qty: " << parse_qty("25x").has_value() << '\n';

    std::variant<long long, std::string> reply = std::string("rejected");  // C++17 variant
    std::cout << std::holds_alternative<std::string>(reply) << ' ' << total(1, 2, 3, 4) << ' '
              << kind(7) << ' ' << kind(2.5) << '\n';
    std::pair lot{kLot, 2.5};  // C++17 deduces std::pair<int, double>
    std::cout << lot.first * lot.second << '\n';
    return 0;
}

